css:
.label-item-name { 
    grid-area: label-item-price;
    font-size: 1.1em;
    font-weight: 600;
}
.label-item-price { 
    grid-area: label-item-price;
    font-size: 1.1em;
    font-weight: 400;
}

.label-field2{
    margin: auto;
    text-align: center;
}

.label-item-code { 
    grid-area: label-item-code;
    width: 100%;
    height: 1.2em;
    font-size: 1.3em;
    overflow-wrap: break-word;
}

.label-item-code-alone { 
    grid-area: label-item-code;
    width: 100%;
    height: 3em;
    font-size: 3em;
    overflow-wrap: break-word;
    margin: auto;
}

.label-item-barcode { 
    grid-area: label-item-barcode;
    width: 100% !important;
    font-size: 0.5em;
    text-align: center;
}
.barcode-container{
    max-width: 100%;
    max-height: 100%;
}

.print-format{
font-family: monosapce;
}

 .barcode-label-container{
    border: 1px solid #d1d8dd;
    display: inline-block;
    resize: both;
    overflow: auto;
    padding:0.5em;
    width: 100%;
    height: 100% 
    
}
 
.dashboard-section{
		display: inline-block;
		resize: both;
		overflow: auto;
}
.label-field{
    margin: auto;
    //border: 1px solid black;
    text-align: center;
    font-family: monosapce;
}

.row:after {
  content: "";
  display: table;
  clear: both;
}

html:
{% set items = doc.items %}
{% set config = frappe.get_doc("QR Code Configuration") %}
{% set show_item_code = config.show_item_code %}
{% set show_item_name = config.show_item_name %}
{% set show_item_price = config.show_item_price %}
{% set item_code_font_size = config.item_code_font_size %}
{% set item_name_font_size = config.item_name_font_size %}
{% set item_price_font_size = config.item_price_font_size %}
{% for item in items  %}
    {% set item_code = item.item_code %}
    {% set item_name = item.item_name %}
    {% set item_price = item.rate %}
    {% set item_serials = item.serial_no %}
    {% set qty = item.qty %}
    {% if item_serials and item_serials is string %}
    {% set serials = item_serials.split('\n') %}
    {% if serials |last == "" %}
    {% set temp = serials.pop() %}
    {% endif %}
    {% for serial in serials %}
          <div class="barcode-label-container">
            {% if show_item_code %}
              <div class="label-item-code label-field" style = "font-size:{{item_code_font_size}}em">
               {{ item_code  }}
              </div>
            {% endif %}
              <div class="label-item-barcode label-field">
                <div class="barcode-container">
                    <img src="{{ get_qr_image(item, docname=doc.name) }}" width="240px"/>
                </div>
              </div>
              <div class = "row2">
                  {% if show_item_name %}
                    <div class="label-item-name label-field2" style = "font-size:{{item_name_font_size}}em">
                          {{ item_name }}
                    </div>
                    {% endif %}
                    {% if show_item_price %}
                    <div class="label-item-price label-field2" style = "font-size:{{item_price_font_size}}em">
                        RM {{"%.2f"|format(item_price)}}
                    </div>
                    {% endif %}
            </div>
        </div>
    {% endfor %}
    {% else %}
        {% for i in range((qty) |round |int ) %}
          <div class="barcode-label-container">
        {% if show_item_code %}
          <div class="label-item-code label-field" style = "font-size:{{item_code_font_size}}em">
           {{ item_code  }}
          </div>
        {% endif %}
              <div class="label-item-barcode label-field">
                <div class="barcode-container">
                    <img src="{{ get_qr_image(item, docname=doc.name) }}" width="240px"/>
                </div>
              </div>
              <div class = "row2">
                  {% if show_item_name %}
                    <div class="label-item-name label-field2" style = "font-size:{{item_name_font_size}}em">
                          {{ item_name }}
                    </div>
                    {% endif %}
                    {% if show_item_price %}
                    <div class="label-item-price label-field2" style = "font-size:{{item_price_font_size}}em">
                        RM {{"%.2f"|format(item_price)}}
                    </div>
                    {% endif %}
            </div>
        </div>
        {% endfor %}
    {% endif%}
{% endfor %}

