html:
{% set items = doc.items %}
{% set config = frappe.get_doc("Barcode Configuration") %}
{% set width = config.width %}
{% set height = config.height %}
{% set display_value = config.display_value == 1 %}
{% set show_item_code = config.show_item_code %}
{% set show_item_name = config.show_item_name %}
{% set show_item_price = config.show_item_price %}
{% set item_code_font_size = config.item_code_font_size %}
{% set item_name_font_size = config.item_name_font_size %}
{% set item_price_font_size = config.item_price_font_size %}

{% for item in items  %}
    {% set barcode_format = item.barcode_type %}
    {% set barcode = item.barcode %}
    {% set item_code = item.item_code %}
    {% set item_name = item.item_name %}
    {% set item_price = item.get_formatted("rate") %}
    {% set item_batch = item.batch_no %}
    {% set item_serials = item.serial_no %}
    {% set qty = item.qty %}
    {% if doc.show_sku %}
    {% for i in range((qty)|round|int ) %}

      <div class="barcode-label-container">
        <div id="barcode-label" class="barcode-label">
          {% if barcode %}
          {% if show_item_code %}
          <div class="label-item-code label-field" style = "font-size:{{item_code_font_size}}em">
           {{ item_code  }}
          </div>
          {% endif %}
          <div class="label-item-barcode label-field">
            <div class="barcode-container">
                <img src="{{ get_barcode_image(barcode, barcode_format, width, height, display_value, doc.name) }}" style="max-width:100%;"/>
            </div>
          </div>
          {% else %}
          <div class="label-item-code-alone label-field">
           {{ item_code  }}
          </div>
          {% endif %}
          <div class = "row2">
                {% if show_item_name %}
                <div class="label-item-name label-field2" style = "font-size:{{item_name_font_size}}em">
                      {{ item_name }}
                </div>
                {% endif %}
                {% if show_item_price %}
                <div class="label-item-price label-field2" style = "font-size:{{item_price_font_size}}em">
                    {{item_price}}
                </div>
                {% endif %}
          </div>
        </div>
      </div>
      {% endfor %}
    {% endif%}
    {# ITEM BATCH NO #}
    {% if doc.show_batch_no %}
    {% set batch_format = doc.batch_barcode_type%}
    {% if item_batch %}
    {% for i in range((qty) |round|int ) %}

      <div class="barcode-label-container">
        <div id="barcode-label" class="barcode-label">
          {% if item_batch %}
          {% if show_item_code %}
          <div class="label-item-code label-field" style = "font-size:{{item_code_font_size}}em">
           {{ item_code  }}
          </div>
          {% endif %}
          <div class="label-item-barcode label-field">
            <div class="barcode-container">
                <img src="{{ get_barcode_image(item_batch, batch_format, width, height, display_value, doc.name) }}" style="max-width:100%;"/>
            </div>
          </div>
          {% endif %}
          <div class = "row2">
                {% if show_item_name %}
                <div class="label-item-name label-field2" style = "font-size:{{item_name_font_size}}em">
                      {{ item_name }}
                </div>
                {% endif %}
                {% if show_item_price %}
                <div class="label-item-price label-field2" style = "font-size:{{item_price_font_size}}em">
                    {{item_price}}
                </div>
                {% endif %}

          </div>
        </div>
      </div>
      {% endfor %}
  {% endif%}
  {%endif %}
  {# ITEM SERIAL NO #}
     {% if doc.show_serial_no  %}
     {% if item_serials and item_serials is string %}
    {% set serial_format = doc.serial_barcode_type%}
    {% set serials = item_serials.split('\n') %}
    {% for serial in serials %}
      <div class="barcode-label-container">
        <div id="barcode-label" class="barcode-label">
          {% if serials %}
          {% if show_item_code %}
          <div class="label-item-code label-field" style = "font-size:{{item_code_font_size}}em">
           {{ item_code  }}
          </div>
          {% endif %}
          <div class="label-item-barcode label-field">
            <div class="barcode-container">
                <img src="{{ get_barcode_image(serial, serial_format, width, height, display_value, doc.name) }}" style="max-width:100%;"/>
            </div>
          </div>

            {% endif %}
            <div class = "row2">
                {% if show_item_name %}
                <div class="label-item-name label-field2" style = "font-size:{{item_name_font_size}}em">
                      {{ item_name }}
                </div>
                {% endif %}
                {% if show_item_price %}
                <div class="label-item-price label-field2" style = "font-size:{{item_price_font_size}}em">
                    {{item_price}}
                </div>
                {% endif %}

           </div>
        </div>
      </div>
      {% endfor %}
  {% endif %}
  {% endif %}
{% endfor %}

